<script>
(function(){
var $=function(i){return document.getElementById(i)};
var AG=[
 {n:"Claude Code",h:"Open Claude Code in any folder, then paste this."},
 {n:"Cursor",h:"Open the Cursor agent chat with terminal access, then paste this."},
 {n:"Codex",h:"Start Codex in any folder, then paste this."}];
var cur=0,url="";
function clean(s){return String(s).replace(/[\u0000-\u001f\u007f]+/g," ").replace(/\s+/g," ").trim().slice(0,300)}
function norm(raw){
 var s=clean(raw);
 if(!s)return null;
 if(/^https?:\/\/\S+$/i.test(s))return{url:s,found:false};
 if(/^[a-z0-9-]+(\.[a-z0-9-]+)+(:\d+)?([\/?#]\S*)?$/i.test(s))return{url:"https://"+s,found:false};
 return{url:"<URL>",found:true,q:s};
}
function build(r){
 var u=r.url,L=[];
 if(r.found){
  L.push('Goal: test the quickstart for "'+r.q+'" the way a new developer would, fix any step that breaks, and prove the fix.');
  L.push('');
  L.push('0. "'+r.q+'" is not a URL. Find the official quickstart page for it, show me the URL, and use it as <URL> below.');
 }else{
  L.push("Goal: test the quickstart at "+u+" the way a new developer would, fix any step that breaks, and prove the fix.");
  L.push('');
 }
 L.push("1. Run `docker info`. If it fails, tell me what is missing and how to fix it. On Windows, use Docker inside WSL and set FIRSTRUN_DOCKER. Stop until it works.");
 L.push("2. Run `pip install git+https://github.com/HighnessAtharva/firstrun`.");
 L.push("3. Check that CLAUDE_CODE_OAUTH_TOKEN is set. If not, ask me to run `claude setup-token` and set it. Never print a secret.");
 L.push("4. Run `firstrun "+u+"`. While it runs, tell me in plain words which repo it uses and which step it is on.");
 L.push("5. Read runs/<id>/report.md. Tell me in 3 to 6 short sentences: which step broke, the error, the class Jev gave it, the fix, and whether a fresh container verified the fix.");
 L.push("6. If the fix is verified and patches the docs, show me the diff and the PR body. Ask \"Open this PR on <repo>?\" and wait for my yes. Open nothing before that.");
 L.push("7. After a yes, run `firstrun pr <id> --json` and run the gh commands it prints.");
 L.push("8. Last, print the line that starts with \"share:\" from the run output, so I can watch the replay.");
 return L.join("\n");
}
function show(){
 var r=norm($("u").value);
 if(!r){$("u").focus();$("u").setAttribute("aria-invalid","true");return}
 $("u").removeAttribute("aria-invalid");
 url=build(r);
 $("out").hidden=false;
 render();
 $("out").scrollIntoView({behavior:matchMedia("(prefers-reduced-motion:reduce)").matches?"auto":"smooth",block:"start"});
}
function render(){
 $("pre").textContent=url;
 $("how").textContent=AG[cur].h;
 for(var i=0;i<3;i++){var t=$("t"+i);t.setAttribute("aria-selected",i===cur);t.tabIndex=i===cur?0:-1}
 $("pre").setAttribute("aria-labelledby","t"+cur);
}
$("f").addEventListener("submit",function(e){e.preventDefault();show()});
$("chips").addEventListener("click",function(e){var u=e.target.getAttribute&&e.target.getAttribute("data-u");if(u){$("u").value=u;show()}});
document.querySelector(".tabs").addEventListener("click",function(e){var i=e.target.getAttribute&&e.target.getAttribute("data-i");if(i!==null&&i!==undefined){cur=+i;render()}});
document.querySelector(".tabs").addEventListener("keydown",function(e){
 if(e.key==="ArrowRight"||e.key==="ArrowLeft"){cur=(cur+(e.key==="ArrowRight"?1:2))%3;render();$("t"+cur).focus()}});
$("cp").addEventListener("click",function(){
 var b=this,t=url;
 (navigator.clipboard?navigator.clipboard.writeText(t):Promise.reject()).then(function(){b.textContent="Copied"},function(){
  var r=document.createRange();r.selectNodeContents($("pre"));var s=getSelection();s.removeAllRanges();s.addRange(r);b.textContent="Press Ctrl+C"});
 setTimeout(function(){b.textContent="Copy prompt"},2000)});
var a=document.querySelectorAll("#ex a[data-n]");
Array.prototype.forEach.call(a,function(el){
 fetch("examples/"+el.getAttribute("data-n")+".txt",{method:"HEAD"}).then(function(r){if(r.ok)el.hidden=false;else el.hidden=true}).catch(function(){el.hidden=true});
});
})();
</script>
